-- analytics, reports, notifications. Generated by Prisma, reordered for a data-preserving
-- upgrade, plus hand-written CHECK constraints and triggers (see the end of this file).

-- Guard: the legacy integration_connections table held encrypted tokens and is replaced by
-- integration_accounts. Refuse to drop it if it contains data (re-connect or migrate manually first).
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM integration_connections) THEN
    RAISE EXCEPTION 'integration_connections contains rows; migrate them to integration_accounts before applying this migration';
  END IF;
END $$;

