-- ---------------------------------------------------------------------------------------------
-- Data backfill for databases that already contain clients (created before agencies existed).
-- A fresh database has no clients, so nothing is created. Role -> permission links are filled by
-- the application (`pnpm db:seed` runs syncRbac); the roles themselves are created here.
-- ---------------------------------------------------------------------------------------------
DO $$
DECLARE v_agency text;
BEGIN
  IF EXISTS (SELECT 1 FROM clients) THEN
    v_agency := gen_random_uuid()::text;
    INSERT INTO agencies (id, name, slug, updated_at) VALUES (v_agency, 'Default Agency', 'default-agency', now());

    UPDATE clients SET agency_id = v_agency;
    UPDATE websites w SET agency_id = c.agency_id FROM clients c WHERE c.id = w.client_id;
    UPDATE job_runs j SET agency_id = c.agency_id FROM clients c WHERE c.id = j.client_id;
    UPDATE audit_log a SET agency_id = c.agency_id FROM clients c WHERE c.id = a.client_id;

    INSERT INTO roles (id, agency_id, scope, key, name, is_system, updated_at)
    SELECT gen_random_uuid()::text, v_agency, s.scope::"RoleScope", s.key, initcap(s.key), true, now()
    FROM (VALUES ('agency','owner'), ('agency','admin'), ('agency','member'),
                 ('client','admin'), ('client','member'), ('client','viewer')) AS s(scope, key);

    -- Everyone who had a client membership becomes a plain agency member and keeps their client role.
    INSERT INTO agency_memberships (id, agency_id, user_id, role_id, status, updated_at)
    SELECT gen_random_uuid()::text, v_agency, u.user_id,
           (SELECT id FROM roles WHERE agency_id = v_agency AND scope = 'agency' AND key = 'member'),
           'active', now()
    FROM (SELECT DISTINCT user_id FROM memberships) u;

    INSERT INTO client_memberships (id, agency_id, client_id, user_id, role_id, status, updated_at)
    SELECT gen_random_uuid()::text, v_agency, m.client_id, m.user_id, r.id, 'active', now()
    FROM memberships m
    JOIN roles r ON r.agency_id = v_agency AND r.scope = 'client' AND r.key = m.role::text;
  END IF;
END $$;

