-- =============================================================================================
-- Integrity rules that Prisma cannot express: CHECK constraints and triggers.
-- Listed in docs/database-erd.md ("Integrity beyond foreign keys").
-- =============================================================================================

-- ---- CHECK constraints ----------------------------------------------------------------------

-- Secrets may only be stored as AES-256-GCM ciphertext from @automation/integrations:
-- "v1.<keyId>.<iv>.<authTag>.<data>". Plaintext tokens are rejected by the database itself.
ALTER TABLE "integration_accounts"
  ADD CONSTRAINT "integration_accounts_credentials_encrypted_chk"
  CHECK ("encrypted_credentials" ~ '^v1\.[0-9a-f]{8}\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+$'),
  ADD CONSTRAINT "integration_accounts_webhook_secret_encrypted_chk"
  CHECK ("encrypted_webhook_secret" IS NULL
         OR "encrypted_webhook_secret" ~ '^v1\.[0-9a-f]{8}\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+$');

ALTER TABLE "task_dependencies"
  ADD CONSTRAINT "task_dependencies_not_self_chk" CHECK ("task_id" <> "depends_on_task_id");

ALTER TABLE "tasks"
  ADD CONSTRAINT "tasks_not_own_parent_chk" CHECK ("parent_task_id" IS NULL OR "parent_task_id" <> "id"),
  ADD CONSTRAINT "tasks_estimate_chk" CHECK ("estimate_minutes" IS NULL OR "estimate_minutes" >= 0);

ALTER TABLE "time_entries"
  ADD CONSTRAINT "time_entries_period_chk" CHECK ("ended_at" IS NULL OR "ended_at" >= "started_at"),
  ADD CONSTRAINT "time_entries_duration_chk" CHECK ("duration_seconds" >= 0),
  ADD CONSTRAINT "time_entries_target_chk" CHECK ("task_id" IS NOT NULL OR "project_id" IS NOT NULL);

ALTER TABLE "reports"
  ADD CONSTRAINT "reports_period_chk" CHECK ("period_end" >= "period_start"),
  ADD CONSTRAINT "reports_revision_chk" CHECK ("revision" >= 1);

-- A decided approval must record when it was decided.
ALTER TABLE "content_approvals"
  ADD CONSTRAINT "content_approvals_decided_chk"
  CHECK ("status" IN ('pending', 'cancelled', 'expired') OR "decided_at" IS NOT NULL);

ALTER TABLE "sync_runs"
  ADD CONSTRAINT "sync_runs_period_chk" CHECK ("finished_at" IS NULL OR "started_at" IS NULL OR "finished_at" >= "started_at"),
  ADD CONSTRAINT "sync_runs_range_chk" CHECK ("covered_from" IS NULL OR "covered_to" IS NULL OR "covered_to" >= "covered_from"),
  ADD CONSTRAINT "sync_runs_counts_chk" CHECK ("rows_fetched" >= 0 AND "rows_written" >= 0);

ALTER TABLE "keyword_rank_snapshots"
  ADD CONSTRAINT "keyword_rank_snapshots_position_chk" CHECK ("position" IS NULL OR "position" >= 1);

ALTER TABLE "task_attachments" ADD CONSTRAINT "task_attachments_size_chk" CHECK ("size_bytes" >= 0);
ALTER TABLE "content_assets" ADD CONSTRAINT "content_assets_size_chk" CHECK ("size_bytes" >= 0);

ALTER TABLE "ai_usage_records"
  ADD CONSTRAINT "ai_usage_records_nonnegative_chk"
  CHECK ("input_tokens" >= 0 AND "output_tokens" >= 0 AND "cached_tokens" >= 0 AND "cost_micros" >= 0);

ALTER TABLE "clients" ADD CONSTRAINT "clients_report_interval_chk" CHECK ("report_interval_days" > 0);

-- ---- Trigger functions ------------------------------------------------------------------------

-- A user referenced by a client-owned row (assignee, time-entry owner, comment author, ...) must
-- actually have access to that client: platform admin, active client member, or agency staff with
-- all-clients access. Column name is passed as the trigger argument.
CREATE FUNCTION assert_user_has_client_access() RETURNS trigger AS $$
DECLARE
  uid text := to_jsonb(NEW) ->> TG_ARGV[0];
BEGIN
  IF uid IS NULL THEN
    RETURN NEW;
  END IF;
  IF EXISTS (SELECT 1 FROM users u WHERE u.id = uid AND u.is_admin)
     OR EXISTS (SELECT 1 FROM client_memberships m
                WHERE m.client_id = NEW.client_id AND m.user_id = uid AND m.status = 'active')
     OR EXISTS (SELECT 1 FROM agency_memberships a
                WHERE a.agency_id = NEW.agency_id AND a.user_id = uid AND a.status = 'active' AND a.all_clients_access)
  THEN
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'user % has no access to client %', uid, NEW.client_id USING ERRCODE = '23514';
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER tasks_assignee_access BEFORE INSERT OR UPDATE OF "assignee_id" ON "tasks"
  FOR EACH ROW EXECUTE FUNCTION assert_user_has_client_access('assignee_id');
CREATE TRIGGER tasks_reporter_access BEFORE INSERT OR UPDATE OF "reporter_id" ON "tasks"
  FOR EACH ROW EXECUTE FUNCTION assert_user_has_client_access('reporter_id');
CREATE TRIGGER time_entries_user_access BEFORE INSERT ON "time_entries"
  FOR EACH ROW EXECUTE FUNCTION assert_user_has_client_access('user_id');
CREATE TRIGGER task_comments_author_access BEFORE INSERT ON "task_comments"
  FOR EACH ROW EXECUTE FUNCTION assert_user_has_client_access('author_id');
CREATE TRIGGER content_items_assignee_access BEFORE INSERT OR UPDATE OF "assigned_to_id" ON "content_items"
  FOR EACH ROW EXECUTE FUNCTION assert_user_has_client_access('assigned_to_id');

-- A membership may only use a role of the matching scope (agency roles for agency seats, ...).
CREATE FUNCTION assert_role_scope() RETURNS trigger AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM roles r WHERE r.id = NEW.role_id AND r.scope::text = TG_ARGV[0]) THEN
    RAISE EXCEPTION 'role % is not a % role', NEW.role_id, TG_ARGV[0] USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER agency_memberships_role_scope BEFORE INSERT OR UPDATE OF "role_id" ON "agency_memberships"
  FOR EACH ROW EXECUTE FUNCTION assert_role_scope('agency');
CREATE TRIGGER client_memberships_role_scope BEFORE INSERT OR UPDATE OF "role_id" ON "client_memberships"
  FOR EACH ROW EXECUTE FUNCTION assert_role_scope('client');

-- Publishing needs an APPROVED approval of exactly this version (CLAUDE.md rule 6). Enforced when
-- the job is created and again before it can move to publishing/succeeded.
CREATE FUNCTION assert_publish_approved() RETURNS trigger AS $$
DECLARE
  s text;
BEGIN
  IF TG_OP = 'UPDATE'
     AND NEW.content_approval_id = OLD.content_approval_id
     AND NEW.status::text NOT IN ('publishing', 'succeeded') THEN
    RETURN NEW;
  END IF;
  SELECT a.status::text INTO s FROM content_approvals a
   WHERE a.id = NEW.content_approval_id AND a.content_version_id = NEW.content_version_id;
  IF s IS DISTINCT FROM 'approved' THEN
    RAISE EXCEPTION 'publishing job requires an approved approval for this content version' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER publishing_jobs_require_approval BEFORE INSERT OR UPDATE ON "publishing_jobs"
  FOR EACH ROW EXECUTE FUNCTION assert_publish_approved();

-- current_version_id must point at a version of THIS item.
CREATE FUNCTION assert_current_version_belongs() RETURNS trigger AS $$
BEGIN
  IF NEW.current_version_id IS NOT NULL AND NOT EXISTS (
       SELECT 1 FROM content_versions v WHERE v.id = NEW.current_version_id AND v.content_item_id = NEW.id) THEN
    RAISE EXCEPTION 'current_version_id must reference a version of the same content item' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER content_items_current_version BEFORE INSERT OR UPDATE OF "current_version_id" ON "content_items"
  FOR EACH ROW EXECUTE FUNCTION assert_current_version_belongs();

-- audit_log.client_id is intentionally not a foreign key (history outlives a client purge), so
-- check on insert that the client exists and belongs to the row's agency.
CREATE FUNCTION assert_audit_client_in_agency() RETURNS trigger AS $$
DECLARE
  client_agency text;
BEGIN
  IF NEW.client_id IS NULL THEN
    RETURN NEW;
  END IF;
  SELECT c.agency_id INTO client_agency FROM clients c WHERE c.id = NEW.client_id;
  IF client_agency IS NULL THEN
    RAISE EXCEPTION 'audit_log.client_id % does not exist', NEW.client_id USING ERRCODE = '23503';
  END IF;
  IF NEW.agency_id IS NULL THEN
    NEW.agency_id := client_agency;
  ELSIF NEW.agency_id <> client_agency THEN
    RAISE EXCEPTION 'client % does not belong to agency %', NEW.client_id, NEW.agency_id USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER audit_log_client_in_agency BEFORE INSERT ON "audit_log"
  FOR EACH ROW EXECUTE FUNCTION assert_audit_client_in_agency();

-- ---- Append-only tables -----------------------------------------------------------------------
-- History must not be edited. Deleting is still allowed for cascades and retention jobs, except on
-- audit_log, which can only be deleted inside a transaction that sets app.allow_purge = 'on'.

CREATE FUNCTION prevent_update() RETURNS trigger AS $$
BEGIN
  RAISE EXCEPTION '% is append-only; insert a new row instead of updating', TG_TABLE_NAME USING ERRCODE = '55000';
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER keyword_rank_snapshots_append_only BEFORE UPDATE ON "keyword_rank_snapshots" FOR EACH ROW EXECUTE FUNCTION prevent_update();
CREATE TRIGGER backlink_snapshots_append_only BEFORE UPDATE ON "backlink_snapshots" FOR EACH ROW EXECUTE FUNCTION prevent_update();
CREATE TRIGGER metric_snapshots_append_only BEFORE UPDATE ON "metric_snapshots" FOR EACH ROW EXECUTE FUNCTION prevent_update();
CREATE TRIGGER post_metric_snapshots_append_only BEFORE UPDATE ON "post_metric_snapshots" FOR EACH ROW EXECUTE FUNCTION prevent_update();
CREATE TRIGGER report_data_snapshots_append_only BEFORE UPDATE ON "report_data_snapshots" FOR EACH ROW EXECUTE FUNCTION prevent_update();
CREATE TRIGGER seo_issue_history_append_only BEFORE UPDATE ON "seo_issue_history" FOR EACH ROW EXECUTE FUNCTION prevent_update();
CREATE TRIGGER task_events_append_only BEFORE UPDATE ON "task_events" FOR EACH ROW EXECUTE FUNCTION prevent_update();
CREATE TRIGGER approval_events_append_only BEFORE UPDATE ON "approval_events" FOR EACH ROW EXECUTE FUNCTION prevent_update();
CREATE TRIGGER ai_usage_records_append_only BEFORE UPDATE ON "ai_usage_records" FOR EACH ROW EXECUTE FUNCTION prevent_update();
CREATE TRIGGER content_versions_immutable BEFORE UPDATE ON "content_versions" FOR EACH ROW EXECUTE FUNCTION prevent_update();

CREATE FUNCTION protect_audit_log() RETURNS trigger AS $$
BEGIN
  IF TG_OP = 'DELETE' AND current_setting('app.allow_purge', true) = 'on' THEN
    RETURN OLD;
  END IF;
  RAISE EXCEPTION 'audit_log is append-only' USING ERRCODE = '55000';
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER audit_log_protect BEFORE UPDATE OR DELETE ON "audit_log" FOR EACH ROW EXECUTE FUNCTION protect_audit_log();
